; Sets the even-frame flag $405c from the frame counter. On even frames, runs the routine for the ground state $4059.
update_plane_state
        lda frame_odd                   ; $405d = flag of the frame before.
        sta frame_odd_prev
        lda frame_count
        and #$01
        sta frame_odd
        beq update_plane_state_dispatch
        rts
update_plane_state_dispatch
        lda plane_state
        beq plane_fly                   ; 0: plane_fly. 1: take-off roll. 3: landing. 4: rollout. 5: service.
        cmp #$01
        beq plane_jump_takeoff
        cmp #$03
        beq plane_jump_landing
        cmp #$04
        beq plane_jump_rollout
        cmp #$05
        beq plane_jump_service
